-- The Librarian — CRM
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'thelibrarian.io' OR LOWER(`name`) = LOWER('The Librarian'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'The Librarian', NULL, 'https://thelibrarian.io', NULL, NULL, 'AI-асистент для агентів з нерухомості: збирає дані клієнтів з голосових нотаток, листів і фото, пам''ятає вподобання кожного, підбирає об''єкти, нагадує про контакти й готує персональні відповіді прямо з телефона.', 'An AI assistant for real estate agents: it captures client details from voice notes, emails and photos, remembers each client''s preferences, matches properties, reminds you about follow-ups and drafts personal replies right from your phone.', 'The Librarian допомагає ріелторам не втрачати клієнтів, коли день розписаний показами. Дані про нових клієнтів можна додавати голосом, текстом, фото чи документом просто на ходу, а асистент перетворює розмову на картку контакту. Він пам''ятає нотатки, вподобання, попередні розмови й вимоги кожного клієнта, швидко підбирає відповідні об''єкти й готує персональні листи та повідомлення з урахуванням усього, що вже знає. Асистент показує, кому час нагадати про себе, щоб жоден контакт не загубився, а щоранку надсилає план дня з важливими клієнтами, завданнями й зустрічами. Для окремих агентів є єдиний тариф із 30 днями безкоштовного користування без картки, для команд і агентств — індивідуальні умови. Є мобільний застосунок.', 'The Librarian helps real estate agents keep clients from slipping away when the day is full of showings. You can add new client details by voice, text, photo or document on the go, and the assistant turns a conversation into a contact record. It remembers notes, preferences, past conversations and requirements for every client, quickly finds matching properties and drafts personal emails and messages using everything it already knows. The assistant shows who needs a follow-up so no contact gets lost, and every morning sends a day plan with key clients, tasks and meetings. Individual agents get a single plan with 30 days free and no card; teams and brokerages get custom terms. There is a mobile app.', 'Додавання клієнтів голосом, текстом чи фото
Пам''ять про вподобання й історію кожного клієнта
Швидкий підбір об''єктів нерухомості
Нагадування, кому потрібно написати
Персональні чернетки відповідей
Щоденний план зі справами й зустрічами
Мобільний застосунок', 'Add clients by voice, text or photo
Memory of each client''s preferences and history
Fast property matching
Reminders about who to contact
Personal reply drafts
Daily plan with tasks and meetings
Mobile app', 'Агенти з нерухомості, а також команди й агентства.', 'Real estate agents, as well as teams and brokerages.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'thelibrarian.io' OR LOWER(`name`) = LOWER('The Librarian')) ORDER BY `id` LIMIT 1);
