-- Mind Map Wizard — Дошки та діаграми
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mindmapwizard.com' OR LOWER(`name`) = LOWER('Mind Map Wizard'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Mind Map Wizard', NULL, 'https://mindmapwizard.com', NULL, NULL, 'AI-генератор ментальних карт: введіть тему або завантажте PDF, зображення, посилання чи відео YouTube — і за секунди отримаєте структуровану карту, яку можна редагувати, поширювати й експортувати.', 'An AI mind map generator: enter a topic or upload a PDF, image, link or YouTube video and get a structured map in seconds that you can edit, share and export.', 'Mind Map Wizard перетворює будь-яку тему чи матеріал на наочну ментальну карту. Достатньо ввести тему, вставити посилання, завантажити PDF чи зображення або дати посилання на відео YouTube — AI проаналізує вміст і побудує структуровану карту. Це зручно, щоб швидко зрозуміти суть документа, статті чи відео, не читаючи й не переглядаючи все повністю. Карту можна редагувати вручну, змінюючи текст будь-якої гілки, або попросити AI-асистента додати гілки, розгорнути тему чи змінити вигляд. Готовою картою можна поділитися за посиланням або експортувати її. Інтерфейс доступний багатьма мовами. Безкоштовно доступні кілька AI-карт із водяним знаком при експорті; річний тариф Pro відкриває сотні карт на місяць, роботу з файлами й посиланнями та експорт без водяного знака.', 'Mind Map Wizard turns any topic or material into a visual mind map. Enter a topic, paste a link, upload a PDF or image, or share a YouTube video link, and the AI analyzes the content and builds a structured map. This makes it easy to grasp the essence of a document, article or video without reading or watching it all. You can edit the map by hand, changing the text of any branch, or ask the AI assistant to add branches, expand a topic or change the look. The finished map can be shared via a link or exported. The interface is available in many languages. A few AI maps are free with a watermark on export; the annual Pro plan unlocks hundreds of maps per month, work with files and links, and watermark-free export.', 'Ментальна карта з теми за секунди
Карти з PDF, зображень, посилань і YouTube
AI-асистент для редагування карти
Ручне редагування гілок
Поширення за посиланням і експорт
Багатомовний інтерфейс', 'A mind map from a topic in seconds
Maps from PDFs, images, links and YouTube
AI assistant for editing the map
Manual branch editing
Sharing via link and export
Multilingual interface', 'Студенти, викладачі й професіонали, які хочуть швидко структурувати тему чи стиснути довгий матеріал.', 'Students, teachers and professionals who want to structure a topic or condense long material quickly.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
