SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'agentvoice.com' OR LOWER(`name`) = LOWER('AgentVoice'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'AgentVoice', NULL, 'https://agentvoice.com', NULL, NULL, 'Агенція AI-голосових агентів: проєктує, створює й супроводжує агентів, які приймають і здійснюють дзвінки, записують на прийом, оновлюють CRM і надсилають SMS після розмови.', 'An AI voice agent agency: it designs, builds and runs agents that answer and make calls, book appointments, update your CRM and send a text after the call.', 'AgentVoice — це не самостійний сервіс, а команда, що будує голосових агентів під завдання конкретного бізнесу. Агенти відповідають на вхідні дзвінки й телефонують самі, записують на прийом, оновлюють записи в CRM, надсилають повідомлення після розмови й переводять дзвінок на людину за потреби. Розмова звучить природно: агент справляється з перебиваннями, фоновим шумом і зміною думки співрозмовника, а також пам''ятає попередні дзвінки й дії в системах. Агентів будують на одній із популярних голосових платформ або на власному рушії компанії, тестують на реальних дзвінках і налаштовують після запуску. Є два формати: індивідуальна розробка під проєкт або разова ліцензія на рушій із вихідним кодом, який розгортається у вашій хмарі. Витрати на голос, AI і телефонію оплачуються за собівартістю.', 'AgentVoice is not a self-serve tool but a team that builds voice agents for a specific business. The agents answer inbound calls and place outbound ones, book appointments, update CRM records, send follow-up messages and transfer the call to a person when needed. Conversations sound natural: the agent handles interruptions, background noise and callers who change their mind, and remembers earlier calls and actions in your systems. Agents are built on one of the popular voice platforms or the company''s own engine, tested on real calls and tuned after launch. There are two formats: a custom build per project, or a one-time license for the engine with source code deployed in your own cloud. Voice, AI and telephony usage is billed at cost.', 'Вхідні й вихідні голосові агенти
Запис на прийом і оновлення CRM
SMS після дзвінка
Природна розмова з перебиваннями
Пам''ять про попередні дзвінки
Переведення на людину й черги
Ліцензія на рушій у власній хмарі', 'Inbound and outbound voice agents
Appointment booking and CRM updates
Text message after the call
Natural conversation with interruptions
Memory of earlier calls
Transfers to a person and queues
Engine license in your own cloud', 'Компанії, яким потрібен індивідуально налаштований голосовий агент для дзвінків.', 'Companies that need a custom-built voice agent for calls.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
