-- Cabina.AI — Чат-боти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'cabina.ai' OR LOWER(`name`) = LOWER('Cabina.AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Cabina.AI', NULL, 'https://cabina.ai', NULL, NULL, 'Робочий простір з багатьма AI-моделями: чат з текстовими моделями різних розробників, генерація зображень і відео, робота з PDF та іншими файлами, транскрипція аудіо й десятки готових текстових інструментів.', 'A workspace with many AI models: chat with language models from different developers, image and video generation, work with PDFs and other files, audio transcription and dozens of ready text tools.', 'Cabina.AI об''єднує в одному інтерфейсі доступ до популярних текстових, графічних, відео- й аудіомоделей різних розробників. У чаті можна працювати з різними мовними моделями й порівнювати їхні відповіді, а також покращувати власні підказки. Завантажені документи — PDF, Word, таблиці — можна підсумовувати, перекладати, аналізувати й переписувати, аудіо та відео — транскрибувати й перекладати. Доступні генерація й редагування зображень, створення відео, озвучення тексту вбудованими чи власними голосами, база знань і понад п''ятдесят швидких дій: перефразування, розширення, спрощення тексту, генерація дописів тощо. Є MCP-сервер і інструмент командного рядка. Інтерфейс підтримує кілька мов, зокрема українську. Тарифи працюють на токенах, є безкоштовний старт.', 'Cabina.AI brings access to popular text, image, video and audio models from different developers into one interface. In the chat you can work with different language models and compare their answers, and improve your own prompts. Uploaded documents such as PDF, Word and spreadsheets can be summarized, translated, analyzed and rewritten, while audio and video can be transcribed and translated. Image generation and editing, video creation, text-to-speech with built-in or custom voices, a knowledge base and more than fifty quick actions such as paraphrasing, expanding, simplifying text and generating posts are available. There is an MCP server and a command-line tool. The interface supports several languages, including Ukrainian. Plans run on tokens, and there is a free start.', 'Багато мовних моделей в одному чаті
Порівняння відповідей моделей
Робота з PDF, документами й таблицями
Транскрипція й переклад аудіо та відео
Генерація зображень і відео
Озвучення тексту
Готові швидкі дії для тексту', 'Many language models in one chat
Comparing model answers
Work with PDFs, documents and spreadsheets
Audio and video transcription and translation
Image and video generation
Text-to-speech
Quick text actions', 'Люди, які користуються різними AI-моделями й хочуть мати їх в одному місці за однією підпискою.', 'People who use different AI models and want them in one place under one subscription.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
