-- Mindsmith — Курси
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mindsmith.ai' OR LOWER(`name`) = LOWER('Mindsmith'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Mindsmith', NULL, 'https://mindsmith.ai', NULL, NULL, 'AI-інструмент для створення електронних курсів: агент перетворює ваші матеріали на інтерактивні уроки з розгалуженими сценаріями, відео й живими розмовами, а вбудована аналітика показує, як навчаються слухачі.', 'An AI tool for creating eLearning courses: an agent turns your materials into interactive lessons with branching scenarios, video and live conversations, and built-in analytics show how learners progress.', 'Mindsmith призначений для дизайнерів навчання й корпоративних команд, які створюють електронні курси. Ви завантажуєте будь-які вихідні матеріали, а AI-агент формує з них урок під ваші навчальні цілі; розкадровка дає змогу триматися джерела дослівно або змінювати подачу на свій розсуд. У редакторі доступні розгалужені сценарії, анімовані відео, живі розмови для тренування навичок, перетворення відео на уроки, переклад курсів і інтеграції. Курсами можна ділитися за посиланням, вбудовувати їх на сайти чи експортувати у форматі SCORM, а аналітика показує результати слухачів. Слухачі користуються безкоштовно, оплата — за кожного автора; освітянам знижка 30%. Безкоштовний тариф дає стартові AI-кредити й необмежене створення контенту зі значком сервісу.', 'Mindsmith is designed for learning designers and corporate teams that create eLearning courses. You upload any source material and an AI agent shapes it into a lesson for your learning objectives; storyboards let you follow the source verbatim or adapt the delivery your way. The editor offers branching scenarios, animated video, live conversations for skill practice, video-to-lesson conversion, course translation and integrations. Courses can be shared via link, embedded on websites or exported as SCORM, and analytics show learner results. Learners always use it for free, pricing is per author, and educators get 30% off. The free plan gives starter AI credits and unlimited content with the service badge.', 'Курс із ваших матеріалів за допомогою AI-агента
Розкадровка для контролю над змістом
Розгалужені сценарії й живі розмови
Анімоване відео й перетворення відео на уроки
Переклад курсів
Поширення, вбудовування й SCORM
Аналітика навчання', 'A course from your materials with an AI agent
Storyboards for control over content
Branching scenarios and live conversations
Animated video and video-to-lesson conversion
Course translation
Sharing, embedding and SCORM
Learning analytics', 'Дизайнери навчання, корпоративні тренери й навчальні заклади.', 'Learning designers, corporate trainers and educational institutions.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
