SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'transcript.lol' OR LOWER(`name`) = LOWER('Transcript LOL'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Transcript LOL', NULL, 'https://transcript.lol', NULL, NULL, 'AI-сервіс транскрипції аудіо й відео: точні розшифровки на основі Whisper з розпізнаванням мовців, імпортом із хмарних сховищ і Zoom, редактором, підсумками та експортом у TXT, DOCX, PDF, SRT і VTT.', 'An AI audio and video transcription service: accurate Whisper-based transcripts with speaker detection, import from cloud storage and Zoom, an editor, summaries and export to TXT, DOCX, PDF, SRT and VTT.', 'Transcript LOL перетворює аудіо- та відеозаписи на текст. Розпізнавання побудоване на моделі OpenAI Whisper, підтримуються власні словники термінів і файли тривалістю до десяти годин. Записи можна завантажити напряму або імпортувати з Google Drive, Dropbox, за посиланням чи із Zoom. Сервіс автоматично розрізняє мовців і підписує їх іменами, а в редакторі доступні пошук і заміна, призначення мовців, форматування й виділення. Готову розшифровку можна експортувати в TXT, DOCX, PDF, а також у формати субтитрів SRT і VTT. Окрім тексту, сервіс готує підсумки, ментальні карти, списки завдань і дозволяє ставити запитання до запису в чаті. Безкоштовно доступні дві короткі розшифровки на день; безлімітний тариф знімає обмеження й пришвидшує обробку. Є мобільний і настільний застосунки.', 'Transcript LOL turns audio and video recordings into text. Recognition is built on the OpenAI Whisper model, with support for custom vocabularies and files up to ten hours long. Recordings can be uploaded directly or imported from Google Drive, Dropbox, a URL or Zoom. The service automatically separates speakers and labels them by name, and the editor offers find and replace, speaker assignment, formatting and highlighting. Finished transcripts can be exported to TXT, DOCX and PDF, as well as SRT and VTT subtitle formats. Beyond text, the service prepares summaries, mind maps and action items and lets you ask questions about the recording in a chat. Two short transcripts a day are free; the unlimited plan removes limits and speeds up processing. There are mobile and desktop apps.', 'Розшифровка аудіо й відео на основі Whisper
Розпізнавання й підписування мовців
Імпорт з Google Drive, Dropbox, Zoom і за посиланням
Редактор розшифровок
Експорт у TXT, DOCX, PDF, SRT і VTT
Підсумки, списки завдань і чат із записом
Файли до 10 годин', 'Whisper-based audio and video transcription
Speaker detection and labeling
Import from Google Drive, Dropbox, Zoom and URLs
Transcript editor
Export to TXT, DOCX, PDF, SRT and VTT
Summaries, action items and chat with the recording
Files up to 10 hours', 'Журналісти, дослідники, студенти й команди, яким потрібні розшифровки інтерв''ю, зустрічей і лекцій.', 'Journalists, researchers, students and teams who need transcripts of interviews, meetings and lectures.', 'web,mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
