-- SciSummary — Дослідження та пошук
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'scisummary.com' OR LOWER(`name`) = LOWER('SciSummary'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SciSummary', NULL, 'https://scisummary.com', NULL, NULL, 'AI для науковців і студентів: стисло підсумовує наукові статті й дослідження, виокремлює анотацію, рисунки, посилання й ключові висновки та працює як менеджер документів і джерел.', 'AI for researchers and students: it concisely summarizes scientific articles and research papers, extracts the abstract, figures, references and key findings, and works as a document and reference manager.', 'SciSummary створено саме для роботи з науковою літературою. Сервіс допомагає зрозуміти дослідницьку статтю: виокремлює анотацію, рисунки й список літератури та підсвічує ключові висновки так, як їх зазвичай читають дослідники, зберігаючи контекст і структуру роботи. Крім підсумків, SciSummary працює як менеджер документів і посилань, де можна впорядковувати прочитані статті. Сервісом користуються студенти й дослідники університетів, а також він є офіційним AI-постачальником для однієї з великих цифрових бібліотек у галузі комп''ютерних наук. Почати можна безкоштовно після реєстрації.', 'SciSummary is built specifically for working with scientific literature. The service helps you understand a research paper: it extracts the abstract, figures and reference list and highlights key findings the way researchers usually read them, preserving the context and structure of the work. Beyond summaries, SciSummary works as a document and reference manager where you can organize the papers you have read. It is used by university students and researchers, and is the official AI provider for one of the major digital libraries in computer science. You can start for free after signing up.', 'Підсумки наукових статей за секунди
Виокремлення анотації, рисунків і посилань
Підсвічування ключових висновків
Менеджер документів і джерел
Безкоштовна реєстрація', 'Summaries of scientific papers in seconds
Extraction of abstract, figures and references
Highlighting of key findings
Document and reference manager
Free sign-up', 'Студенти, аспіранти й науковці, які працюють з великою кількістю статей.', 'Students, graduate students and researchers who work with many papers.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
