SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'emergent.sh' OR LOWER(`name`) = LOWER('Emergent'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Emergent', NULL, 'https://emergent.sh', NULL, NULL, 'Платформа для створення веб- і мобільних застосунків через розмову з AI-агентами, без коду: від ідеї до готового до запуску застосунку за кілька хвилин, з хостингом, інтеграцією з GitHub і вбудованими AI-моделями.', 'A platform for building web and mobile apps through a conversation with AI agents, no code: from idea to a launch-ready app in minutes, with hosting, GitHub integration and built-in AI models.', 'Emergent дозволяє будувати повноцінні веб- і мобільні застосунки, просто описуючи їх у розмові. AI-агенти платформи пишуть застосунок, який можна одразу запускати, а підключити мовні моделі до власного продукту можна в один клік. На платних тарифах доступні приватний хостинг проєктів, інтеграція з GitHub, відгалуження завдань і докупівля кредитів. Старший тариф додає дуже велике контекстне вікно, режим поглибленого міркування, редагування системних інструкцій, створення власних AI-агентів і пріоритетну підтримку. Для великих компаній є окремі умови. Безкоштовний тариф дає невелику кількість кредитів щомісяця без картки.', 'Emergent lets you build full web and mobile apps simply by describing them in a conversation. The platform''s AI agents write an app you can launch right away, and you can connect language models to your own product in one click. Paid plans add private project hosting, GitHub integration, task forking and extra credit purchases. The top plan adds a very large context window, an extended reasoning mode, system prompt editing, creating your own AI agents and priority support. Large companies get separate terms. The free plan gives a small number of credits each month with no card.', 'Веб- і мобільні застосунки через розмову
AI-агенти, що пишуть застосунок
Підключення мовних моделей в один клік
