SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'getvoila.ai' OR LOWER(`name`) = LOWER('Voilà'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Voilà', NULL, 'https://getvoila.ai', NULL, NULL, 'AI-асистент, що працює на будь-якому сайті через розширення браузера, а також у настільному й мобільному застосунках: чат зі сторінками, документами й зображеннями, підсумки, переклад, відповіді на листи й генерація зображень.', 'An AI assistant that works on any website through a browser extension, as well as in desktop and mobile apps: chat with pages, documents and images, summaries, translation, email replies and image generation.', 'Voilà вбудовується у звичну роботу й розуміє контекст того, що ви робите, тож не потрібно перемикатися між інструментами. Асистент читає вебсторінки, статті, посилання й листування в пошті та допомагає їх підсумувати, переписати, перекласти, швидко відповісти чи створити новий текст. Можна спілкуватися з документами, зображеннями й відео YouTube, досліджувати тему з надійними джерелами та генерувати зображення. Є бібліотека готових експертних підказок і можливість зберігати власні. Voilà доступний як розширення браузера, настільний і мобільний застосунок. Безкоштовно доступна обмежена кількість запитів; платні тарифи додають тисячі або необмежені запити, веб-доступ і роботу з документами. Також можна підключити власний ключ API.', 'Voilà blends into your usual work and understands the context of what you are doing, so you do not have to switch between tools. The assistant reads web pages, articles, links and email threads and helps you summarize, rewrite, translate, reply quickly or create new text. You can chat with documents, images and YouTube videos, research a topic with reliable sources and generate images. There is a library of ready expert prompts and the option to save your own. Voilà is available as a browser extension, a desktop app and a mobile app. A limited number of requests are free; paid plans add thousands of or unlimited requests, web access and document chat. You can also connect your own API key.', 'Робота на будь-якому сайті через розширення
Підсумки, переписування й переклад
Швидкі відповіді на листи
Чат із документами, зображеннями й YouTube
Генерація зображень
Бібліотека підказок
Настільний і мобільний застосунки', 'Works on any website via the extension
Summaries, rewriting and translation
Quick email replies
Chat with documents, images and YouTube
Image generation
Prompt library
Desktop and mobile apps', 'Професіонали, які багато працюють із текстом і хочуть мати AI-помічника просто в браузері.', 'Professionals who work with a lot of text and want an AI helper right in the browser.', 'web,desktop,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
