SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gentube.app' OR LOWER(`name`) = LOWER('GenTube'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'GenTube', NULL, 'https://gentube.app', NULL, NULL, 'AI-конструктор персонажів: створіть власного персонажа приблизно за хвилину, досліджуйте його світ, діліться ним і грайте з персонажами інших користувачів або створюйте ремікси в різних художніх стилях.', 'An AI character maker: create your own character in about a minute, explore its world, share it and play with other users'' characters or remix them in different art styles.', 'GenTube — творчий сервіс для створення персонажів за допомогою AI. Ви описуєте ідею, і приблизно за хвилину отримуєте власного персонажа, якого можна розвивати далі, досліджувати його світ і запрошувати інших до спільної гри. У загальній стрічці видно персонажів, створених спільнотою, а в розділі авторів можна обрати творця й зробити ремікс у його стилі — від акварелі до інших художніх напрямів. Сервіс безкоштовний, швидкий і не обмежує кількість створень.', 'GenTube is a creative service for making characters with AI. You describe an idea and in about a minute get your own character that you can develop further, explore its world and invite others to play together. The shared feed shows characters made by the community, and in the creators section you can pick a creator and remix in their style, from watercolor to other art movements. The service is free, fast and does not limit the number of creations.', 'Створення персонажа приблизно за хвилину
Світи персонажів і спільна гра
Стрічка персонажів спільноти
Ремікси в стилях інших авторів
Безкоштовно й без обмежень', 'A character in about a minute
Character worlds and playing together
Community character feed
Remixes in other creators'' styles
Free and unlimited', 'Автори фан-творчості, художники-аматори й усі, хто любить вигадувати персонажів.', 'Fan creators, hobby artists and anyone who loves inventing characters.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
