-- TheySaid — Аналітика
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'theysaid.io' OR LOWER(`name`) = LOWER('TheySaid'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TheySaid', NULL, 'https://theysaid.io', NULL, NULL, 'Платформа збору відгуків з AI: тестування зручності, інтерв''ю, опитування й голосування, де AI ставить уточнювальні запитання, модерує сесії та сам аналізує відповіді й готує звіти.', 'An AI feedback platform: usability tests, interviews, surveys and polls where AI asks follow-up questions, moderates sessions and analyzes answers and prepares reports itself.', 'TheySaid допомагає продуктовим командам отримувати відгуки користувачів так само швидко, як вони випускають новий код і дизайн. Платформа замінює розрізнені інструменти: тестування зручності, інтерв''ю, форми, опитування, голосування та регулярні пульс-опитування працюють в одному місці. Користувачі дають відгук у формі розмови з AI, який ставить уточнювальні запитання й допомагає з''ясувати причини поведінки, а не лише зафіксувати відповіді. AI також допомагає створити проєкт дослідження, модерує тести, виокремлює теми з якісних відгуків і готує аналітику та звіти без годин ручного розбору. Збирати відповіді можна за посиланням або залучати учасників із панелі сервісу за окрему плату. Безкоштовний тариф дає кілька AI-тестів і десятки опитувань на місяць без картки; для організацій є корпоративний план.', 'TheySaid helps product teams get user feedback as fast as they ship new code and design. The platform replaces scattered tools: usability tests, interviews, forms, surveys, polls and regular pulse surveys all work in one place. Users give feedback as a conversation with AI that asks follow-up questions and helps uncover why people behave the way they do, not just record answers. AI also helps set up a research project, moderates tests, extracts themes from qualitative feedback and prepares analytics and reports without hours of manual review. You can collect responses via a link or recruit participants from the service''s panel for an extra fee. The free plan gives a few AI tests and dozens of surveys per month with no card; organizations get an enterprise plan.', 'AI-тестування зручності з уточнювальними запитаннями
Автоматизовані інтерв''ю з користувачами
AI-опитування, форми й голосування
AI-модерація тестів
Автоматичний аналіз і звіти
Збір відгуків за посиланням
Залучення учасників із панелі', 'AI usability tests with follow-up questions
Automated user interviews
AI surveys, forms and polls
AI test moderation
Automatic analysis and reports
Feedback collection via link
Participant recruiting from a panel', 'Продуктові команди, UX-дослідники й дизайнери.', 'Product teams, UX researchers and designers.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
