-- BotDojo — AI-агенти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'botdojo.com' OR LOWER(`name`) = LOWER('BotDojo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'BotDojo', NULL, 'https://botdojo.com', NULL, NULL, 'Платформа AI-агентів для бізнес-процесів компаній: агенти працюють у ваших CRM, телефонії, тікетах, документах і Slack, спілкуються через чат, голос і пошту та залишають людині рішення там, де потрібне судження.', 'An AI agent platform for company workflows: agents work inside your CRM, telephony, tickets, docs and Slack, communicate via chat, voice and email, and leave decisions to people where judgment matters.', 'BotDojo вбудовує AI-агентів у процеси, якими компанія вже користується. Агентам можна доручати роботу через чат, голос чи електронну пошту, ставити запитання й отримувати звіти. Вони підключаються до CRM, телефонії, систем заявок, документів, Slack і процедур погодження, тож можуть не лише відповідати, а й виконувати завдання — наприклад, перетворити чергу дзвінків на оновлені заявки. Платформа дає змогу оркеструвати кількох агентів для складних задач, контролювати результати, виправляти нестандартні випадки й поступово покращувати роботу. Готові агенти спеціалізуються на операційній ефективності, аналізі даних, управлінні знаннями й автоматизації процесів. Сервіс орієнтований на великі компанії з вимогами до контролю, тепер входить до екосистеми Mitratech ARIES; співпраця починається з демонстрації.', 'BotDojo embeds AI agents into the processes a company already uses. You can assign work to agents through chat, voice or email, ask questions and receive reports. They connect to CRM, telephony, ticketing systems, documents, Slack and approval procedures, so they can do more than answer: for example, turn a call backlog into updated tickets. The platform lets you orchestrate several agents for complex tasks, monitor results, correct edge cases and improve performance over time. Ready agents specialize in operational efficiency, data analysis, knowledge management and workflow automation. The service targets large companies with governance requirements and is now part of the Mitratech ARIES ecosystem; engagement starts with a demo.', 'Агенти в CRM, телефонії, тікетах, документах і Slack
Робота з агентами через чат, голос і пошту
Оркестрація кількох агентів
Участь людини в критичних рішеннях
Контроль і поступове покращення результатів
Агенти для аналізу даних і управління знаннями', 'Agents in CRM, telephony, tickets, docs and Slack
Work with agents via chat, voice and email
Orchestration of several agents
Human involvement in critical decisions
Monitoring and gradual improvement
Agents for data analysis and knowledge management', 'Середні й великі компанії, які автоматизують операційні процеси AI-агентами.', 'Mid-size and large companies automating operational processes with AI agents.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
