-- Postiz — SMM
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'postiz.com' OR LOWER(`name`) = LOWER('Postiz'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Postiz', NULL, 'https://postiz.com', NULL, NULL, 'Планувальник публікацій у соцмережах для роботи з AI-агентами: Claude, ChatGPT чи інші агенти через MCP, CLI та API готують і плануть дописи в понад 30 мереж, а ви переглядаєте все в одному календарі.', 'A social media scheduler built for AI agents: Claude, ChatGPT or other agents use MCP, a CLI and an API to draft and schedule posts to 30+ networks while you review everything in one calendar.', 'Postiz дозволяє вести соцмережі на автопілоті з допомогою AI-агентів або класичним способом. Ви просите Claude, ChatGPT чи іншого агента підготувати контент-план, і агент через MCP-сервер або інструмент командного рядка Postiz створює й планує дописи в понад 30 мережах; переглянути й підправити все можна у візуальному календарі. Розробники можуть будувати власні застосунки для публікацій на основі публічного API та SDK, а команди автоматизації — підключати Postiz до n8n чи Make. У сервісі є редактор зображень, AI-помічник, генерація зображень і відео, нарізка відео на кліпи, кросспостинг, повторювані дописи, відкладені публікації, автопостинг з RSS, підписи, групи клієнтів і аналітика. Усі тарифи включають MCP, CLI та API; є 7-денний безкоштовний пробний період.', 'Postiz lets you run social media on autopilot with AI agents or the classic way. You ask Claude, ChatGPT or another agent to prepare a content plan, and the agent uses the Postiz MCP server or command-line tool to create and schedule posts across more than 30 networks; you can review and adjust everything in a visual calendar. Developers can build their own posting apps on the public API and SDK, and automation teams can connect Postiz to n8n or Make. The service includes an image editor, an AI copilot, image and video generation, video clipping, cross-posting, repeated posts, delayed publishing, RSS auto-posting, signatures, customer groups and analytics. Every plan includes MCP, CLI and API; there is a 7-day free trial.', 'Планування дописів у понад 30 соцмереж
Робота через Claude, ChatGPT та інших агентів (MCP, CLI)
Візуальний календар публікацій
Публічний API, SDK і вебхуки
Інтеграція з n8n і Make
Генерація зображень і відео, нарізка кліпів
Кросспостинг, RSS і аналітика', 'Scheduling posts to 30+ social networks
Works via Claude, ChatGPT and other agents (MCP, CLI)
Visual publishing calendar
Public API, SDK and webhooks
n8n and Make integration
Image and video generation, video clipping
Cross-posting, RSS and analytics', 'SMM-фахівці, автори контенту, агенції та розробники, які автоматизують публікації.', 'Social media managers, content creators, agencies and developers automating publishing.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
