SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kreadoai.com' OR LOWER(`name`) = LOWER('KreadoAI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'KreadoAI', NULL, 'https://kreadoai.com', NULL, NULL, 'AI-генератор рекламних креативів: з опису товару створює відео з аватарами-ведучими, зображення й тексти для реклами, з понад тисячею аватарів, перекладом відео на десятки мов і експортом під різні платформи.', 'An AI ad creative generator: from a product description it creates videos with AI presenters, images and ad copy, with 1,000+ avatars, video translation into dozens of languages and export for different platforms.', 'KreadoAI допомагає швидко створювати рекламу для онлайн-продажів. Сервіс перетворює ідею чи опис товару на готові відео, зображення й тексти. Для відео доступні генерація з тексту чи зображення, відео з AI-ведучим, фотоаватари, перетворення презентацій і PDF на відео з аватаром, відео за посиланням, пакетне створення роликів для TikTok і відео в стилі контенту від користувачів. Для зображень є генератор рекламних креативів і загальний генератор. Окремо доступні озвучення тексту, швидке клонування голосу, видалення фону, збільшення роздільності, домальовування й розширення зображень, переклад відео та зображень і генерація банерів різних розмірів для рекламних майданчиків. Інтерфейс доступний кількома мовами; можна платити щомісяця або разово.', 'KreadoAI helps you create ads for online sales quickly. The service turns an idea or product description into ready videos, images and copy. Video options include generation from text or an image, AI presenter videos, photo avatars, turning presentations and PDFs into avatar videos, video from a URL, batch TikTok videos and user-generated-style videos. For images there is an ad creative generator and a general image generator. Text-to-speech, instant voice cloning, background removal, upscaling, inpainting and image extension, video and image translation and multi-size banner generation for ad platforms are also available. The interface comes in several languages; you can pay monthly or one-off.', 'Рекламні відео з тексту, зображення чи посилання
AI-ведучі й фотоаватари
Відео з презентацій і PDF
Генератор рекламних креативів
Озвучення й клонування голосу
Переклад відео й зображень
Банери різних розмірів', 'Ad videos from text, an image or a URL
AI presenters and photo avatars
Videos from presentations and PDFs
Ad creative generator
Text-to-speech and voice cloning
Video and image translation
Multi-size banners', 'Інтернет-магазини, маркетологи й агенції, яким потрібно швидко створювати рекламу для різних ринків.', 'Online stores, marketers and agencies that need to create ads for different markets quickly.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
