-- Syft — Лідогенерація
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'syftdata.com' OR LOWER(`name`) = LOWER('Syft'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Syft', NULL, 'https://syftdata.com', NULL, NULL, 'Сервіс для B2B-маркетингу: на основі відвідувань сайту й реакцій у LinkedIn визначає конкретних потенційних клієнтів із наміром купити та автоматично запускає персональні email-, LinkedIn- і рекламні кампанії.', 'A B2B marketing service: based on website visits and LinkedIn engagement it identifies specific prospects with buying intent and automatically triggers personalized email, LinkedIn and ad campaigns.', 'Syft допомагає B2B-командам не втрачати зацікавлених відвідувачів. Більшість людей переглядає сайт анонімно або реєструється з особистою поштою, тому відділ продажів їх не бачить. Сервіс визначає людей і компанії, які відповідають профілю ідеального клієнта й виявляють намір купити, — за відвідуваннями сайту та взаємодіями в LinkedIn. Далі він оцінює їх і автоматично запускає персональні кампанії через пошту, LinkedIn і рекламу, щоб команда встигала звернутися вчасно й домовлялася про більше зустрічей. На старшому тарифі доступні сигнали з дописів і реклами в LinkedIn, автоматизація розсилок у LinkedIn і детальна аналітика. Налаштування займає близько десяти хвилин; є 14-денний пробний період без картки, а також партнерська програма для агенцій.', 'Syft helps B2B teams stop losing interested visitors. Most people browse a website anonymously or sign up with a personal email, so the sales team never sees them. The service identifies people and companies that match your ideal customer profile and show buying intent, based on website visits and LinkedIn interactions. It then qualifies them and automatically launches personalized campaigns through email, LinkedIn and ads, so the team reaches out in time and books more meetings. The higher plan adds signals from LinkedIn posts and ads, LinkedIn outreach automation and drill-down analytics. Setup takes about ten minutes; there is a 14-day trial with no card and a partner program for agencies.', 'Визначення відвідувачів сайту з наміром купити
Сигнали з взаємодій у LinkedIn
Кваліфікація за профілем ідеального клієнта
Автоматичні кампанії в пошті, LinkedIn і рекламі
Необмежені місця й компанії
Детальна аналітика (Pro)', 'Identifies website visitors with buying intent
Signals from LinkedIn engagement
Qualification by ideal customer profile
Automatic email, LinkedIn and ad campaigns
Unlimited seats and companies
Drill-down analytics (Pro)', 'Маркетингові й продажні команди B2B-компаній, а також агенції.', 'Marketing and sales teams at B2B companies, as well as agencies.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
