-- PrometAI — Документи
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'prometai.app' OR LOWER(`name`) = LOWER('PrometAI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PrometAI', NULL, 'https://prometai.app', NULL, NULL, 'AI-генератор бізнес-планів: за кілька хвилин перетворює вашу ідею на структурований план із фінансовими розрахунками, придатний для банку, кредитора, візової служби чи інвесторів.', 'An AI business plan generator: within minutes it turns your idea into a structured plan with financial projections, suitable for a bank, lender, visa office or investors.', 'PrometAI допомагає засновникам скласти професійний бізнес-план без довгої ручної роботи. Сервіс крок за кроком проводить від ідеї до структурованого документа з потрібними розділами й реальними фінансовими розрахунками, тож перший варіант зазвичай вдається завершити за один раз. Тарифи орієнтовані на конкретну мету: план, який приймуть у банку чи в кредитора, документ для візової служби або детальний план для інвесторів. Безкоштовний тариф дозволяє спробувати сервіс без обмеження в часі, платні мають гарантію повернення коштів, а при квартальній чи річній оплаті діють знижки. Компанія також запустила платформу з понад сотнею інструментів для ранніх етапів підприємництва.', 'PrometAI helps founders build a professional business plan without long manual work. The service guides you step by step from an idea to a structured document with the right sections and real financial projections, so the first draft can usually be finished in one sitting. Plans are aimed at a specific goal: a plan a bank or lender will accept, a document for a visa office, or a detailed plan for investors. The free plan lets you try the service with no time limit, paid plans come with a money-back guarantee, and quarterly or annual billing is discounted. The company has also launched a platform with more than a hundred tools for the early stages of entrepreneurship.', 'Бізнес-план з ідеї за кілька хвилин
Покрокове заповнення розділів
Фінансові розрахунки
Плани для банку, візи чи інвесторів
Гарантія повернення коштів', 'A business plan from an idea in minutes
Step-by-step section filling
Financial projections
Plans for a bank, visa or investors
Money-back guarantee', 'Засновники стартапів і підприємці, яким потрібен бізнес-план для кредиту, візи чи інвестицій.', 'Startup founders and entrepreneurs who need a business plan for a loan, visa or investment.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
