SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'myaininja.com' OR LOWER(`name`) = LOWER('myAIninja'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'myAIninja', NULL, 'https://myaininja.com', NULL, NULL, 'AI-помічник для контенту в соцмережах (франкомовний інтерфейс): на основі вашого профілю, діяльності й стилю пропонує ідеї та пише дописи для LinkedIn, каруселі, статті для блогу й контент-плани.', 'An AI helper for social media content (French-language interface): based on your profile, business and style it suggests ideas and writes LinkedIn posts, carousels, blog articles and content calendars.', 'myAIninja допомагає створювати контент для соцмереж і блогу значно швидше. Ви розповідаєте сервісу про себе, свою діяльність, аудиторію й манеру письма, а AI пропонує ідеї публікацій, що відповідають вашому стилю. Будь-яку ідею можна в один клік перетворити на допис, карусель або довгу статтю для блогу з ілюстраціями; оформлення каруселей налаштовується перед публікацією. Сервіс також складає редакційні календарі. Інтерфейс і сайт сервісу французькою мовою.', 'myAIninja helps you create social media and blog content much faster. You tell the service about yourself, your business, your audience and your writing style, and the AI suggests post ideas that match your voice. Any idea can be turned in one click into a post, a carousel or a long blog article with illustrations; carousel layouts can be customized before publishing. The service also builds editorial calendars. The interface and website are in French.', 'Ідеї публікацій на основі вашого профілю
Дописи для LinkedIn у вашому стилі
Каруселі з налаштовуваним оформленням
Статті для блогу з ілюстраціями
Редакційні календарі', 'Post ideas based on your profile
LinkedIn posts in your style
Carousels with customizable layout
Blog articles with illustrations
Editorial calendars', 'Фрилансери, підприємці й експерти, які ведуть LinkedIn і блог (франкомовні користувачі).', 'Freelancers, entrepreneurs and experts who run LinkedIn and a blog (French-speaking users).', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
