SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mindmapai.app' OR LOWER(`name`) = LOWER('MindMap AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'MindMap AI', NULL, 'https://mindmapai.app', NULL, NULL, 'AI-генератор ментальних карт, що будує карту на основі вашого вмісту — думки, PDF, відео, аудіо чи вебсторінки — і дає уточнювати її в чаті або вручну; ручне редагування безкоштовне без обмежень.', 'An AI mind map generator that builds the map from your own content (a thought, PDF, video, audio or web page) and lets you refine it in chat or by hand; manual editing is free and unlimited.', 'MindMap AI створює ментальні карти, які спираються на ваш власний матеріал. Почати можна з короткої думки чи запитання, документа PDF, запису зустрічі, відео чи аудіо (з виділенням рішень і відповідальних) або вебсторінки й листа через розширення браузера. Карту можна обговорювати з AI в чаті — попросити розгорнути гілку, переорганізувати розділ чи пояснити поняття — і водночас редагувати вручну перетягуванням; обидва способи синхронізовані, історія змін зберігається. Підтримується понад 29 мов. Сервіс працює всередині Claude, ChatGPT та інших асистентів через MCP. Ручна робота з картами безкоштовна й необмежена: проєкти, макети, теми, експорт у PDF, PNG і Markdown, імпорт з інших програм, публікація за посиланням. Платні плани додають більше AI-кредитів; є місячна, річна й довічна оплата, а також веб, iOS, Android і розширення.', 'MindMap AI creates mind maps grounded in your own material. You can start from a short thought or question, a PDF document, a meeting recording, video or audio (with decisions and owners extracted), or a web page and email via the browser extension. You can discuss the map with AI in a chat, asking it to expand a branch, reorganize a section or explain a concept, while also editing by hand with drag and drop; both stay in sync and history is always kept. More than 29 languages are supported. The service works inside Claude, ChatGPT and other assistants via MCP. Manual mapping is free and unlimited: projects, layouts, themes, export to PDF, PNG and Markdown, import from other tools, publishing via link. Paid plans add more AI credits, with monthly, yearly and lifetime billing; it runs on web, iOS, Android and as a browser extension.', 'Карти з думки, PDF, відео, аудіо чи вебсторінки
Уточнення карти в чаті з AI
Ручне редагування без обмежень
Понад 29 мов
Робота через MCP у Claude і ChatGPT
Експорт у PDF, PNG, Markdown
Веб, iOS, Android і розширення браузера', 'Maps from a thought, PDF, video, audio or web page
Refine the map in chat with AI
Unlimited manual editing
29+ languages
Works via MCP in Claude and ChatGPT
Export to PDF, PNG, Markdown
Web, iOS, Android and browser extension', 'Студенти, дослідники й команди, які структурують інформацію в ментальних картах.', 'Students, researchers and teams who structure information in mind maps.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
