SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'onspace.ai' OR LOWER(`name`) = LOWER('OnSpace.AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'OnSpace.AI', NULL, 'https://onspace.ai', NULL, NULL, 'No-code конструктор мобільних і вебзастосунків з AI-агентом: від ідеї до застосунку для iOS, Android чи вебу за хвилини, з керованим бекендом, вбудованими оплатами Stripe і мобільним застосунком для роботи з телефона.', 'A no-code builder for mobile and web apps with an AI agent: from idea to an iOS, Android or web app in minutes, with a managed backend, built-in Stripe payments and a mobile app for building from your phone.', 'OnSpace.AI дозволяє створювати мобільні застосунки, вебзастосунки й лендінги без програмування. Ви описуєте ідею, а AI-агент збирає застосунок, який можна одразу запускати на iOS, Android і у вебі. Бекенд повністю керований: база даних, авторизація, серверні функції, секрети й журнали вже налаштовані, тож не потрібні DevOps-навички. Вбудована інтеграція зі Stripe дає змогу швидко почати приймати оплати. Для досвідчених користувачів є редактор коду, а мобільний застосунок дозволяє створювати й редагувати проєкти просто з телефона. Безкоштовний тариф дає щоденні кредити й публічні проєкти; платний додає більше кредитів, потужніші моделі, приватні проєкти, власні домени й прибирає значок сервісу.', 'OnSpace.AI lets you create mobile apps, web apps and landing pages without programming. You describe an idea and the AI agent assembles an app you can launch right away on iOS, Android and the web. The backend is fully managed: database, authentication, server functions, secrets and logs are already set up, so no DevOps skills are needed. Built-in Stripe integration lets you start taking payments quickly. Experienced users get a code editor, and the mobile app lets you create and edit projects right from your phone. The free plan gives daily credits and public projects; the paid plan adds more credits, stronger models, private projects and custom domains, and removes the service badge.', 'Застосунки для iOS, Android і вебу з опису
Режим AI-агента
Керований бекенд: база, авторизація, функції
Вбудовані оплати Stripe
Редактор коду
Мобільний застосунок для створення проєктів
Власні домени (Pro)', 'iOS, Android and web apps from a description
AI agent mode
Managed backend: database, auth, functions
Built-in Stripe payments
