SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pixpal.chat' OR LOWER(`name`) = LOWER('PixPal'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PixPal', NULL, 'https://pixpal.chat', NULL, NULL, 'Безкоштовний AI-редактор фото й генератор зображень у форматі чату: без реєстрації й водяних знаків генерує картинки, редагує фото, поєднує кілька знімків, реставрує старі фото й перетворює зображення на відео.', 'A free AI photo editor and image generator in a chat format: with no sign-up or watermarks it generates pictures, edits photos, merges several shots, restores old photos and turns images into video.', 'PixPal — творчий AI-помічник, з яким працюють у форматі розмови. Можна безкоштовно й без реєстрації генерувати зображення за описом або попросити сервіс здивувати вас. Завантажені фото можна редагувати: точно додавати чи прибирати об''єкти, поєднувати кілька знімків, переробляти зображення в іншому художньому стилі, реставрувати старі фото й створювати професійні портрети. Окремо доступне перетворення зображення чи текстового опису на короткий відеокліп зі звуком для соцмереж. У налаштуваннях можна обрати модель генерації зображень і модель для чату. Сервіс безкоштовний, без реєстрації та водяних знаків.', 'PixPal is a creative AI companion you work with as a conversation. You can generate images from a description for free and without signing up, or ask the service to surprise you. Uploaded photos can be edited: precisely add or remove objects, merge several shots, remix an image in another art style, restore old photos and create professional headshots. You can also turn an image or a text description into a short video clip with sound for social media. In the settings you can choose the image generation model and the chat model. The service is free, with no sign-up and no watermarks.', 'Генерація зображень у чаті
Редагування фото: додавання й видалення об''єктів
Поєднання кількох фото
Реставрація старих знімків
Професійні портрети
Відео зі зображення зі звуком
Без реєстрації й водяних знаків', 'Image generation in chat
Photo editing: add and remove objects
Merging several photos
Restoring old photos
Professional headshots
Video with sound from an image
No sign-up or watermarks', 'Усі, кому потрібно швидко й безкоштовно згенерувати чи відредагувати зображення.', 'Anyone who needs to generate or edit images quickly and for free.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
