SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'vidu.com' OR LOWER(`name`) = LOWER('Vidu'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Vidu', NULL, 'https://vidu.com', NULL, NULL, 'AI-генератор відео з тексту, зображення чи референсів зі звуком, для соцмереж, реклами й коротких фільмів; має режим реального часу, AI-агента, шаблони, мобільний застосунок і API.', 'An AI video generator from text, an image or references with sound, for social media, ads and short films; it has a real-time mode, an AI agent, templates, a mobile app and an API.', 'Vidu — платформа для створення відео за допомогою власних моделей генерації. Відео можна створювати з текстового опису, з зображення або на основі кількох референсів, зберігаючи узгодженість персонажів між кадрами; доступна також генерація зображень. Ролики мають звук і підходять для соцмереж, інтернет-торгівлі, реклами, анімації й коротких фільмів, а функція розумного монтажу допомагає зібрати готове відео. Окремо доступні модель реального часу, яка реагує на запити практично миттєво, AI-агент для спільної роботи над проєктом, набір інструментів і шаблонів, мобільний застосунок для створення відео будь-де, а також API для розробників. Є індивідуальні й корпоративні плани та програма для авторів.', 'Vidu is a platform for creating video with its own generation models. Videos can be created from a text description, from an image or from several references while keeping characters consistent across shots; image generation is also available. Clips include sound and suit social media, e-commerce, ads, animation and short films, and a smart cuts feature helps assemble a finished video. Also available are a real-time model that responds almost instantly, an AI agent for working on a project together, a set of tools and templates, a mobile app for creating video anywhere and an API for developers. There are individual and enterprise plans and a creator program.', 'Відео з тексту, зображення чи референсів
