-- VoiceType — Транскрипція
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'voicetype.com' OR LOWER(`name`) = LOWER('VoiceType'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'VoiceType', NULL, 'https://voicetype.com', NULL, NULL, 'AI-диктування для будь-яких програм: перетворює мовлення на текст, автоматично прибирає слова-паразити, форматує й покращує написане, щоб писати значно швидше, ніж на клавіатурі.', 'AI dictation for any app: it turns speech into text, automatically removes filler words, formats and improves the writing, so you write much faster than on a keyboard.', 'VoiceType дозволяє писати голосом у будь-якій програмі, де ви зазвичай друкуєте. Сервіс розшифровує сказане, прибирає «е-е», повтори й обмовки, автоматично форматує текст і покращує формулювання, тож на виході виходить охайний текст, а не сира розшифровка. Це зручно для листів, нотаток, документів і повідомлень. Є безкоштовний пробний період на кілька днів, після чого діє підписка з необмеженими розшифровками; також пропонується довічний доступ з разовою оплатою.', 'VoiceType lets you write by voice in any program where you normally type. The service transcribes what you say, removes filler sounds, repetitions and slips, formats the text automatically and improves the wording, so you get clean text rather than a raw transcript. It is handy for emails, notes, documents and messages. There is a free trial of a few days, after which a subscription with unlimited transcriptions applies; lifetime access with a one-time payment is also offered.', 'Диктування в будь-якій програмі
Прибирання слів-паразитів і обмовок
Автоматичне форматування тексту
Покращення формулювань
Необмежені розшифровки на платному плані', 'Dictation in any app
Removal of filler words and slips
Automatic text formatting
Improved wording
Unlimited transcriptions on the paid plan', 'Люди, які багато пишуть і хочуть заощадити час на наборі тексту.', 'People who write a lot and want to save time on typing.', 'web,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
