-- AuthorVoices — Озвучення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'authorvoices.ai' OR LOWER(`name`) = LOWER('AuthorVoices'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'AuthorVoices', NULL, 'https://authorvoices.ai', NULL, NULL, 'AI-озвучення аудіокниг для незалежних авторів і видавців: перетворює рукопис на професійну аудіокнигу з підібраними голосами оповідачів, редагуванням по розділах, прослуховуванням і готовим до дистрибуції аудіо.', 'AI audiobook narration for independent authors and publishers: it turns a manuscript into a professional audiobook with curated narrator voices, chapter-by-chapter editing, previews and distribution-ready audio.', 'AuthorVoices допомагає авторам випустити аудіоверсію своєї книжки без студії й найму диктора. Ви завантажуєте рукопис, обираєте одного з підібраних AI-оповідачів, чоловічих чи жіночих голосів, і сервіс озвучує книжку. Кожен розділ можна редагувати окремо, а перед повним рендером — прослухати фрагмент. Готове аудіо експортується у вигляді, придатному для розповсюдження на аудіокнижкових платформах. Оплата відбувається за кредити без обов''язкової підписки: можна купити озвучення однієї книжки з урахуванням її обсягу, а невикористані кредити не згорають. Для видавців, які випускають кілька книжок щомісяця, є студійні підписки з фіксованою оплатою. Спробувати голоси можна безкоштовно.', 'AuthorVoices helps authors release an audio version of their book without a studio or hiring a narrator. You upload the manuscript, choose one of the curated AI narrators, male or female voices, and the service narrates the book. Each chapter can be edited separately, and you can preview a passage before the full render. The finished audio is exported in a form suitable for distribution on audiobook platforms. Payment is by credits with no mandatory subscription: you can buy narration for a single book based on its length, and unused credits never expire. Publishers producing several books a month can choose studio subscriptions with a flat fee. You can try the voices for free.', 'Аудіокнига з рукопису
Вибір AI-оповідача
Редагування по розділах
Миттєве прослуховування фрагментів
Аудіо, готове до дистрибуції
Оплата за книжку без підписки
Студійні плани для видавців', 'An audiobook from a manuscript
Choice of AI narrator
Chapter-by-chapter editing
Instant passage previews
Distribution-ready audio
Pay per book with no subscription
Studio plans for publishers', 'Незалежні автори й невеликі видавництва.', 'Independent authors and small publishers.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
