INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'AuthorVoices helps authors release an audio version of their book without a studio or hiring a narrator. You upload the manuscript, choose one of the curated AI narrators, male or female voices, and the service narrates the book. Each chapter can be edited separately, and you can preview a passage before the full render. The finished audio is exported in a form suitable for distribution on audiobook platforms. Payment is by credits with no mandatory subscription: you can buy narration for a single book based on its length, and unused credits never expire. Publishers producing several books a month can choose studio subscriptions with a flat fee. You can try the voices for free.', 'manual' FROM DUAL WHERE @new = 1;
