SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'lovestudy.ai' OR LOWER(`name`) = LOWER('LoveStudy.ai'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'LoveStudy.ai', NULL, 'https://lovestudy.ai', NULL, NULL, 'AI-інструмент для навчання: перетворює PDF, презентації, тексти й фото на конспекти, картки для запам''ятовування, тести й навчальні подкасти будь-якою мовою.', 'An AI study tool: it turns PDFs, presentations, texts and photos into notes, flashcards, quizzes and study podcasts in any language.', 'LoveStudy.ai допомагає вчитися ефективніше з власних матеріалів. Завантажте PDF, документ, текстовий файл, презентацію чи фото сторінок, оберіть формат і мову — сервіс автоматично створить конспект, набір карток для запам''ятовування, тест або навчальний подкаст. Матеріалами можна поділитися з іншими або залишити їх приватними. Серед додаткових інструментів є, зокрема, інструменти для вивчення Біблії з тематичним пошуком і роботою з давньогрецьким та давньоєврейським текстом. Без входу доступна невелика кількість безкоштовних кредитів, після реєстрації — трохи більше; платні тарифи дають сотні й тисячі генерацій на місяць і пріоритетну чергу.', 'LoveStudy.ai helps you study more efficiently from your own materials. Upload a PDF, document, text file, presentation or photos of pages, choose a format and language, and the service automatically creates notes, a set of flashcards, a quiz or a study podcast. Materials can be shared with others or kept private. Additional tools include Bible study tools with topical search and work with Greek and Hebrew text. A small number of free credits are available without logging in, and a few more after signing up; paid plans give hundreds or thousands of generations per month and a priority queue.', 'Конспекти з документів
Картки для запам''ятовування з фото й книжок
Тести з PDF і презентацій
Навчальні подкаси з матеріалів
Будь-яка мова результату
Приватні або публічні матеріали', 'Notes from documents
Flashcards from photos and books
Quizzes from PDFs and presentations
Study podcasts from materials
Any output language
Private or public materials', 'Школярі, студенти й усі, хто вчиться самостійно.', 'School and college students and self-learners.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
