INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'God of Prompt', NULL, 'https://godofprompt.ai', NULL, NULL, 'Набір ресурсів для роботи з AI: тисячі підготовлених промптів для ChatGPT, Claude, Gemini і Grok, власні GPT із системними інструкціями, no-code автоматизації, генератор промптів і каталог AI-інструментів.', 'A set of AI resources: thousands of engineered prompts for ChatGPT, Claude, Gemini and Grok, custom GPTs with system instructions, no-code automations, a prompt generator and an AI tools directory.', 'God of Prompt збирає в одному місці ресурси, які допомагають отримувати від AI-моделей професійний результат. Основа — бібліотека з тисяч підготовлених промптів за десятками категорій, яка регулярно поповнюється. Крім неї, є готові власні GPT із повними системними інструкціями, no-code автоматизації, покрокові посібники, генератор промптів і каталог AI-інструментів. Усе можна отримати окремими продуктами або одним комплектом із довічним доступом і оновленнями. Анонсовано помічника, який автоматично підставлятиме контекст вашого бізнесу в кожен промпт.', 'God of Prompt gathers in one place resources that help you get professional results from AI models. Its core is a library of thousands of engineered prompts across dozens of categories that is updated regularly. There are also ready custom GPTs with full system instructions, no-code automations, step-by-step guides, a prompt generator and an AI tools directory. Everything is available as separate products or as one bundle with lifetime access and updates. A copilot that automatically adds your business context to every prompt has been announced.', 'Бібліотека з тисяч промптів
Власні GPT із системними інструкціями
No-code автоматизації
Генератор промптів
Посібники з AI
Каталог AI-інструментів
Комплект із довічним доступом', 'Library of thousands of prompts
Custom GPTs with system instructions
No-code automations
Prompt generator
AI guides
AI tools directory
Bundle with lifetime access', 'Підприємці, маркетологи й фрилансери, які активно користуються ChatGPT, Claude та іншими моделями.', 'Entrepreneurs, marketers and freelancers who actively use ChatGPT, Claude and other models.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
