SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'magiclight.ai' OR LOWER(`name`) = LOWER('MagicLight'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'MagicLight', NULL, 'https://magiclight.ai', NULL, NULL, 'AI-генератор довгих відео: перетворює ідею, сценарій чи історію на завершене відео до 50 хвилин з кількома сценами, узгодженими персонажами й плавною анімацією; є шаблони історій.', 'An AI long-form video generator: it turns an idea, script or story into a finished video up to 50 minutes long with several scenes, consistent characters and smooth animation; story templates are available.', 'MagicLight створений для повноцінних відео, а не окремих коротких кліпів. Сервіс перетворює ідею, сценарій або історію на завершений ролик тривалістю до 50 хвилин з кількома сценами, у яких персонажі рухаються природно, а візуальний стиль лишається узгодженим від початку до кінця. Щоб не починати з чистого аркуша, є бібліотека шаблонів: дитячі казки, релігійні історії, мультфільми, пояснювальні відео, джингли, відео з зображення та створення в один клік. Генерація персонажів і зображень безкоштовна, відео експортуються в 1080p без водяного знака з комерційною ліцензією. Платні плани відрізняються кількістю кредитів і хвилин генерації; спробувати можна безкоштовно без картки.', 'MagicLight is built for complete videos rather than separate short clips. The service turns an idea, script or story into a finished video up to 50 minutes long with several scenes, where characters move naturally and the visual style stays consistent from start to finish. To avoid starting from a blank page there is a template library: kids'' stories, faith stories, cartoons, explainers, jingles, image-to-video and one-click creation. Character and image generation is free, and videos export in 1080p without a watermark and with a commercial license. Paid plans differ in credits and minutes of generation; you can try it for free with no card.', 'Відео до 50 хвилин з ідеї чи сценарію
Кілька сцен з узгодженими персонажами
Шаблони історій
Безкоштовна генерація персонажів і зображень
1080p без водяного знака
Комерційна ліцензія', 'Videos up to 50 minutes from an idea or script
Several scenes with consistent characters
Story templates
Free character and image generation
1080p without watermark
Commercial license', 'Автори YouTube-каналів, освітнього й дитячого контенту, яким потрібні довгі анімовані відео.', 'YouTube creators and makers of educational and children''s content who need long animated videos.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
