-- Kilo Code — Асистенти коду
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kilo.ai' OR LOWER(`name`) = LOWER('Kilo Code'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Kilo Code', NULL, 'https://kilo.ai', NULL, NULL, 'AI-агент для програмування з відкритим кодом: працює у VS Code, JetBrains, командному рядку й хмарі, дає доступ до сотень моделей без націнки, підтримує власні ключі й локальні моделі.', 'An open-source AI coding agent: it works in VS Code, JetBrains, the terminal and the cloud, gives access to hundreds of models with no markup, and supports your own keys and local models.', 'Kilo — агент для програмування з відкритим кодом, який можна використовувати в редакторах VS Code та JetBrains, у терміналі й у хмарі. Він пише й доповнює код, виконує багатокрокові завдання й керує кількома агентами з однієї панелі, зокрема паралельно в ізольованих робочих копіях. Розробник може обрати будь-яку з сотень моделей — від передових до відкритих — і платити за них за собівартістю без націнки, підключити власні ключі або працювати з локальними моделями, щоб код не залишав комп''ютер. Для індивідуальних розробників розширення безкоштовні (використання моделей оплачується окремо); командний план додає аналітику, спільні режими агентів, централізовану оплату й керування командою, корпоративний — SSO, журнали аудиту й обмеження моделей. Kilo нещодавно придбала компанія Anaconda.', 'Kilo is an open-source coding agent you can use in VS Code and JetBrains editors, in the terminal and in the cloud. It writes and completes code, performs multi-step tasks and manages several agents from one panel, including in parallel isolated worktrees. Developers can choose any of hundreds of models, from frontier to open-weight, and pay for them at cost with no markup, connect their own keys or work with local models so the code never leaves the computer. For individual developers the extensions are free (model usage is billed separately); the team plan adds analytics, shared agent modes, centralized billing and team management, and the enterprise plan adds SSO, audit logs and model restrictions. Kilo was recently acquired by Anaconda.', 'Відкритий код
VS Code, JetBrains, термінал і хмара
Сотні моделей без націнки
Власні ключі й локальні моделі
Кілька агентів паралельно
Генерація й доповнення коду
Командна аналітика й керування', 'Open source
VS Code, JetBrains, terminal and cloud
Hundreds of models with no markup
Own keys and local models
Several agents in parallel
Code generation and completion
Team analytics and management', 'Розробники й команди розробки.', 'Developers and development teams.', 'web,desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
