INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Werd', NULL, 'https://werd.ai', NULL, NULL, 'AI-сервіс для створення контенту з командою агентів: ви описуєте ідею в чаті, а агенти-автори, маркетологи й дослідники складають контент-стратегію з урахуванням SEO, пишуть і редагують тексти.', 'An AI content creation service with a team of agents: you describe an idea in a chat, and writer, marketer and researcher agents build an SEO-informed content strategy, then write and edit the texts.', 'Werd дозволяє писати так, як ви думаєте: достатньо описати ідею в чаті, а команда AI-агентів — авторів, маркетингових стратегів і дослідників — сама планує, ухвалює рішення й виконує роботу. Одним кліком сервіс створює документ контент-стратегії з урахуванням SEO під ваші цілі; він зберігається в пам''яті й використовується на всіх етапах, від дослідження до редагування, щоб тексти були змістовними, а не шаблонними. Матеріали оцінюються й оптимізуються з урахуванням актуальних пошукових трендів і намірів за ключовими словами, а вбудований редактор дозволяє доопрацьовувати текст в одному місці. Є безкоштовний пробний період.', 'Werd lets you write the way you think: describe an idea in a chat and a team of AI agents, writers, marketing strategists and researchers, plans, makes decisions and does the work. With one click the service creates an SEO-informed content strategy document tailored to your goals; it is stored in memory and used at every stage from research to editing, so the texts are substantive rather than generic. Content is scored and optimized against current search trends and keyword intent, and the built-in editor lets you refine text in one place. There is a free trial.', 'Команда AI-агентів для контенту
Контент-стратегія з урахуванням SEO
Пам''ять про вашу стратегію
Оптимізація під пошукові тренди
Вбудований AI-редактор', 'A team of AI agents for content
SEO-informed content strategy
Memory of your strategy
Optimization for search trends
Built-in AI editor', 'Маркетологи, автори контенту й команди, що створюють SEO-матеріали.', 'Marketers, content creators and teams producing SEO content.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
