SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pdftovideo.ai' OR LOWER(`name`) = LOWER('PDF to Video AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PDF to Video AI', NULL, 'https://pdftovideo.ai', NULL, NULL, 'Онлайн-сервіс, що перетворює PDF, посилання на статті, довгі тексти чи просто тему на пояснювальне відео з озвученням для навчання, соцмереж і маркетингу — без реєстрації.', 'An online service that turns PDFs, article links, long texts or just a topic into an explainer video with voiceover for learning, social media and marketing, with no sign-up.', 'PDF to Video AI допомагає перетворити документ на коротке пояснювальне відео. Можна завантажити PDF до 80 сторінок, вставити текст, дати посилання на статтю або описати тему підказкою. Перед генерацією обирається формат кадру, тривалість, голос озвучення, тема оформлення та швидкість, після чого сервіс створює готове відео. Так зручно подавати презентації, звіти, інструкції чи навчальні матеріали у форматі, який легше сприймати й поширювати в соцмережах. Є галерея прикладів і новіший режим створення відео з ширшим вибором стилів. Користуватися можна онлайн без реєстрації.', 'PDF to Video AI helps turn a document into a short explainer video. You can upload a PDF of up to 80 pages, paste text, give an article link or describe a topic in a prompt. Before generating you choose the frame format, duration, voiceover, theme and speed, and the service creates a finished video. This makes it easy to present slides, reports, manuals or learning materials in a format that is easier to absorb and share on social media. There is an examples gallery and a newer video creation mode with more styles. It works online with no sign-up.', 'Відео з PDF до 80 сторінок
Відео з тексту, теми чи посилання на статтю
Вибір формату, тривалості й голосу
Теми оформлення
Без реєстрації', 'Video from a PDF of up to 80 pages
Video from text, a topic or an article link
Choice of format, duration and voice
Themes
No sign-up', 'Викладачі, студенти, автори контенту й маркетологи, які хочуть подати документи у форматі відео.', 'Teachers, students, content creators and marketers who want to present documents as video.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
