SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aiassistworks.com' OR LOWER(`name`) = LOWER('AiAssistWorks'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'AiAssistWorks', NULL, 'https://aiassistworks.com', NULL, NULL, 'AI-доповнення для Google Таблиць, Документів і Презентацій: за звичайною командою заповнює тисячі рядків, створює формули, діаграми й зведені таблиці, пише документи й слайди, працюючи з понад сотнею моделей.', 'An AI add-on for Google Sheets, Docs and Slides: from a plain command it fills thousands of rows, creates formulas, charts and pivot tables, and writes documents and slides using 100+ models.', 'AiAssistWorks вбудовує AI безпосередньо в Google Таблиці, Документи й Презентації. У таблицях достатньо описати завдання звичайною мовою, і доповнення пакетно заповнить тисячі рядків, створить формули, діаграми, зведені таблиці, перевірку даних і форматування, а також класифікує, витягне чи очистить дані. У документах і презентаціях воно генерує й редагує тексти та слайди, перекладає й створює зображення. Це замінює постійне копіювання підказок у ChatGPT для повторюваних завдань. Доповнення працює з понад сотнею моделей від OpenAI, Anthropic, Google та інших провайдерів через ваш власний ключ API, тож використання моделей оплачується окремо. Для легкого використання є безкоштовний план; платний відкриває всі функції без обмежень.', 'AiAssistWorks builds AI right into Google Sheets, Docs and Slides. In spreadsheets you describe the task in plain language and the add-on batch-fills thousands of rows, creates formulas, charts, pivot tables, data validation and formatting, and also classifies, extracts or cleans data. In documents and presentations it generates and edits text and slides, translates and creates images. This replaces repeatedly copying prompts into ChatGPT for routine tasks. The add-on works with more than a hundred models from OpenAI, Anthropic, Google and other providers through your own API key, so model usage is billed separately. There is a free plan for light use; the paid plan unlocks all features without limits.', 'Пакетне заповнення Google Таблиць
Формули, діаграми й зведені таблиці за командою
Очищення, класифікація й витягування даних
Генерація документів і слайдів
Понад 100 AI-моделей
Робота з власним ключем API', 'Batch filling of Google Sheets
Formulas, charts and pivot tables by command
Data cleaning, classification and extraction
Document and slide generation
100+ AI models
Works with your own API key', 'Аналітики, маркетологи й офісні працівники, які багато працюють у Google Workspace.', 'Analysts, marketers and office workers who work a lot in Google Workspace.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
