SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'visualgpt.io' OR LOWER(`name`) = LOWER('VisualGPT'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'VisualGPT', NULL, 'https://visualgpt.io', NULL, NULL, 'AI-набір для інтернет-магазинів і авторів: предметні фото товарів, віртуальна примірка на AI-моделях, рекламні креативи, портрети, зміна одягу й зачіски, генерація зображень і відео та нарізка довгих відео на кліпи.', 'An AI suite for online stores and creators: product photos, virtual try-on on AI models, ad creatives, headshots, outfit and hairstyle changes, image and video generation and clipping long videos into shorts.', 'VisualGPT поєднує кілька десятків AI-моделей в одному творчому інструменті. Для продавців є створення предметних фото товарів, віртуальна примірка одягу на реалістичних AI-моделях, повні набори зображень для карток товарів і рекламні креативи. Для авторів і всіх охочих — зміна одягу й зачіски на фото, генератор поз, редактор зображень, ділові портрети без студії, перетворення фото на ескіз, генерація зображень і відео з тексту. Окремий інструмент автоматично знаходить яскраві моменти в довгому відео й нарізає їх на кліпи. Результати без водяних знаків, а на окремих платних планах — з правом комерційного використання. Тарифи працюють на кредитах; почати можна безкоштовно.', 'VisualGPT combines a few dozen AI models in one creative tool. For sellers there are product photos, virtual try-on of clothing on realistic AI models, complete image sets for product listings and ad creatives. For creators and anyone else there are outfit and hairstyle changes on photos, a pose generator, an image editor, professional headshots without a studio, photo-to-sketch conversion, and image and video generation from text. A separate tool automatically finds standout moments in a long video and cuts them into clips. Output has no watermarks and, on eligible paid plans, can be used commercially. Plans run on credits; you can start for free.', 'Предметні фото товарів
Віртуальна примірка на AI-моделях
Рекламні креативи
Зміна одягу, зачіски й пози
Ділові портрети
Генерація зображень і відео
Нарізка довгих відео на кліпи', 'Product photos
Virtual try-on on AI models
Ad creatives
Outfit, hairstyle and pose changes
Professional headshots
Image and video generation
Clipping long videos', 'Інтернет-магазини, продавці на маркетплейсах і автори контенту.', 'Online stores, marketplace sellers and content creators.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
