INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'VisualGPT combines a few dozen AI models in one creative tool. For sellers there are product photos, virtual try-on of clothing on realistic AI models, complete image sets for product listings and ad creatives. For creators and anyone else there are outfit and hairstyle changes on photos, a pose generator, an image editor, professional headshots without a studio, photo-to-sketch conversion, and image and video generation from text. A separate tool automatically finds standout moments in a long video and cuts them into clips. Output has no watermarks and, on eligible paid plans, can be used commercially. Plans run on credits; you can start for free.', 'manual' FROM DUAL WHERE @new = 1;
