-- StarterPilot — Конструктори сайтів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'starterpilot.com' OR LOWER(`name`) = LOWER('StarterPilot'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'StarterPilot', NULL, 'https://starterpilot.com', NULL, NULL, 'AI-платформа для запуску бізнесу за одну сесію: перевіряє попит на ідею, придумує назву й логотип, будує редагований лендінг, підключає домен і публікує проєкт на карті стартапів платформи.', 'An AI platform for launching a business in one session: it validates demand for an idea, comes up with a name and logo, builds an editable landing page, connects a domain and publishes the project on the platform''s startup map.', 'StarterPilot допомагає перейти від ідеї до запущеного проєкту за один вечір. Ви описуєте ідею, вказуючи аудиторію, цілі й обмеження, а AI-помічник перевіряє попит, пропонує назву, створює логотип і будує лендінг, який можна редагувати в реальному часі. На сторінку можна додати лист очікування й контактну форму, підключити власний домен із безкоштовним SSL-сертифікатом і опублікувати проєкт. Наявні компанії можуть розмістити себе на карті StarterPilot Earth Map, щоб отримати увагу, голоси, заявки й перших прихильників. Є місячна підписка з 7-денним пробним періодом і разова оплата довічного доступу з необмеженою кількістю проєктів.', 'StarterPilot helps you go from an idea to a launched project in one evening. You describe the idea, mentioning your audience, goals and constraints, and an AI copilot validates demand, suggests a name, creates a logo and builds a landing page you can edit in real time. You can add a waitlist and a contact form, connect your own domain with a free SSL certificate and publish the project. Existing companies can list themselves on the StarterPilot Earth Map to gain exposure, upvotes, leads and early supporters. There is a monthly subscription with a 7-day trial and a one-time lifetime payment with unlimited projects.', 'Перевірка попиту на ідею
Назва й логотип з AI
Лендінг із редагуванням у реальному часі
Лист очікування й контактна форма
Власний домен і SSL
Публікація на карті стартапів', 'Idea demand validation
AI name and logo
Landing page with real-time editing
Waitlist and contact form
Custom domain and SSL
Listing on the startup map', 'Початківці-підприємці й автори, які хочуть швидко перевірити й запустити ідею.', 'Beginner entrepreneurs and creators who want to test and launch an idea quickly.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
