-- 2pr — SMM
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = '2pr.io' OR LOWER(`name`) = LOWER('2pr'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT '2pr', NULL, 'https://2pr.io', NULL, NULL, 'AI-агент для зростання в LinkedIn: збирає трендові теми, пише дописи й каруселі вашим голосом, планує публікації, допомагає відповідати на коментарі та показує аналітику — через офіційний API LinkedIn.', 'An AI agent for growing on LinkedIn: it gathers trending topics, writes posts and carousels in your voice, schedules publishing, helps reply to comments and shows analytics, using the official LinkedIn API.', '2pr об''єднує все, що потрібно для регулярного ведення LinkedIn. Сервіс збирає трендові теми з кількох джерел і має бібліотеку популярних дописів для натхнення. Чернетки пишуться вашим голосом, причому щоразу пропонується кілька варіантів поруч, а генератор вступів допомагає зачепити читача. Можна вставити статтю, відео YouTube чи подкаст — і отримати з нього допис; AI-інтерв''ю ставить запитання, щоб витягнути з вас особисті історії. Також доступні каруселі й зображення під LinkedIn, планування в календарі, швидкі відповіді на коментарі вашим стилем, детальна аналітика з порадами та підключення до Claude чи інших агентів через MCP. Робота йде через офіційний API, без збереження cookies. Є безкоштовний пробний період.', '2pr brings together everything needed to run LinkedIn consistently. The service gathers trending topics from several sources and has a library of popular posts for inspiration. Drafts are written in your voice, with several variants side by side every time, and a hook generator helps grab the reader. You can paste an article, YouTube video or podcast and get a post from it; AI interviews ask questions to draw personal stories out of you. Also available are LinkedIn-tailored carousels and images, calendar scheduling, quick comment replies in your style, detailed analytics with coaching, and connection to Claude or other agents via MCP. It works through the official API without storing cookies. There is a free trial.', 'Трендові теми й бібліотека популярних дописів
Чернетки вашим голосом у кількох варіантах
Дописи зі статей, YouTube і подкастів
Каруселі й зображення для LinkedIn
Планування публікацій
Відповіді на коментарі
Аналітика й MCP', 'Trending topics and a library of popular posts
Drafts in your voice in several variants
Posts from articles, YouTube and podcasts
LinkedIn carousels and images
Post scheduling
Comment replies
Analytics and MCP', 'Засновники, експерти й фахівці, які розвивають особистий бренд у LinkedIn.', 'Founders, experts and professionals building a personal brand on LinkedIn.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
