-- FlowPost — SMM
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'flowpost.ai' OR LOWER(`name`) = LOWER('FlowPost'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'FlowPost', NULL, 'https://flowpost.ai', NULL, NULL, 'AI-автопілот для соцмереж: вивчає ваш стиль за наявним контентом, а потім створює, планує й публікує дописи у дев''ять платформ, зокрема LinkedIn, Instagram, TikTok, YouTube і Google Business Profile.', 'An AI autopilot for social media: it learns your style from existing content, then creates, schedules and publishes posts to nine platforms including LinkedIn, Instagram, TikTok, YouTube and Google Business Profile.', 'FlowPost допомагає підтримувати соцмережі активними, не відкриваючи їх щодня. Сервіс аналізує ваш наявний контент, щоб зрозуміти тон, стиль і улюблені теми, і на цій основі готує дописи, які звучать ближче до вашого бренду, ніж типові AI-тексти. Режим автопілота сам створює й публікує контент за розкладом, навіть коли ви не онлайн. Підтримуються LinkedIn, Instagram, Facebook, X, Threads, Pinterest, YouTube, TikTok і Google Business Profile, а також керування взаємодією з аудиторією. AI-кредити витрачаються на написання текстів, створення зображень і відео; власний текст і медіа можна публікувати без витрати кредитів. Почати можна безкоштовно без картки.', 'FlowPost helps keep social channels active without opening them every day. The service analyzes your existing content to learn your tone, style and recurring themes, and uses that to draft posts that sound closer to your brand than typical AI text. Autopilot mode creates and publishes content on schedule even when you are offline. LinkedIn, Instagram, Facebook, X, Threads, Pinterest, YouTube, TikTok and Google Business Profile are supported, along with engagement management. AI credits are spent on writing text and creating images and videos; your own text and media can be published without spending credits. You can start for free with no card.', 'Вивчення вашого стилю за наявним контентом
Автопілот створення й публікації
Дев''ять соцмереж
Генерація зображень і відео
Керування взаємодією з аудиторією
Публікація власного контенту без кредитів', 'Learns your style from existing content
Autopilot creation and publishing
Nine social networks
Image and video generation
Engagement management
Publishing your own content without credits', 'Підприємці, експерти й малий бізнес, яким потрібна регулярна присутність у соцмережах.', 'Entrepreneurs, experts and small businesses that need a regular social media presence.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
