INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'FlowPost helps keep social channels active without opening them every day. The service analyzes your existing content to learn your tone, style and recurring themes, and uses that to draft posts that sound closer to your brand than typical AI text. Autopilot mode creates and publishes content on schedule even when you are offline. LinkedIn, Instagram, Facebook, X, Threads, Pinterest, YouTube, TikTok and Google Business Profile are supported, along with engagement management. AI credits are spent on writing text and creating images and videos; your own text and media can be published without spending credits. You can start for free with no card.', 'manual' FROM DUAL WHERE @new = 1;
