-- FineVoice — Озвучення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'finevoice.ai' OR LOWER(`name`) = LOWER('FineVoice'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'FineVoice', NULL, 'https://finevoice.ai', NULL, NULL, 'Набір AI-інструментів для звуку: озвучення тексту, зміна й клонування голосу, переклад мовлення, синхронізація губ, покращення якості голосу, генерація музики й звукових ефектів для відео й подкастів.', 'A set of AI audio tools: text-to-speech, voice changing and cloning, speech translation, lip sync, voice enhancement, and music and sound effect generation for video and podcasts.', 'FineVoice поєднує багато аудіоінструментів в одному сервісі. Можна перетворити текст на природне мовлення з виразними голосами, змінити свій голос на інший, у тому числі в реальному часі, клонувати голос, перекласти мовлення іншою мовою, синхронізувати губи на відео чи фото, покращити якість запису, розшифрувати мовлення в текст, а також згенерувати фонову музику й звукові ефекти. Є бібліотеки голосів і звуків, генератор подкастів і «говорячі» фото, аудіоагент і API для розробників, а також настільні застосунки. Сервіс підходить для озвучення відео на YouTube, реклами, навчальних матеріалів, подкастів і аудіокниг. Спробувати базові функції можна безкоштовно без реєстрації. Клонувати слід лише власний голос або голос людини, що дала згоду.', 'FineVoice combines many audio tools in one service. You can turn text into natural speech with expressive voices, change your voice into another, including in real time, clone a voice, translate speech into another language, lip-sync a video or photo, enhance recording quality, transcribe speech to text, and generate background music and sound effects. There are voice and sound libraries, a podcast generator and talking photos, an audio agent and an API for developers, as well as desktop apps. The service suits voiceovers for YouTube videos, ads, learning materials, podcasts and audiobooks. Basic features can be tried for free without signing up. Only clone your own voice or that of someone who has given consent.', 'Озвучення тексту
Зміна голосу, зокрема в реальному часі
Клонування голосу
Переклад мовлення й синхронізація губ
Покращення якості й розшифровка мовлення
Музика й звукові ефекти
API й настільні застосунки', 'Text-to-speech
Voice changing, including real time
Voice cloning
Speech translation and lip sync
Voice enhancement and speech-to-text
Music and sound effects
API and desktop apps', 'Автори відео, подкастів і аудіокниг, маркетологи й викладачі.', 'Video, podcast and audiobook creators, marketers and teachers.', 'web,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
