-- Synexa AI — API
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'synexa.ai' OR LOWER(`name`) = LOWER('Synexa AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Synexa AI', NULL, 'https://synexa.ai', NULL, NULL, 'Платформа для запуску AI-моделей через API одним рядком коду: генерація зображень, відео, 3D-моделей і мовлення, реставрація й підписування зображень, дотренування моделей, з оплатою лише за результат.', 'A platform for running AI models via API with one line of code: image, video, 3D and speech generation, image restoration and captioning, model fine-tuning, paying only for output.', 'Synexa AI дозволяє розробникам підключати готові AI-моделі до своїх продуктів без налаштування серверів. Запит надсилається через HTTP, Node.js чи Python одним рядком коду, а в галереї доступні популярні моделі генерації зображень, відео, 3D-моделей і мовлення, а також моделі для реставрації й автоматичного підписування зображень; підтримується й дотренування моделей. Оплата залежить від фактичного використання: за кожне згенероване зображення, відео чи 3D-модель, а для власних задач доступна оренда потужних графічних процесорів. Сервіс позиціонує себе як недорогу альтернативу іншим провайдерам безсерверного AI.', 'Synexa AI lets developers plug ready AI models into their products without setting up servers. A request is sent via HTTP, Node.js or Python in one line of code, and the gallery offers popular models for generating images, video, 3D models and speech, as well as models for image restoration and automatic captioning; model fine-tuning is supported too. Pricing depends on actual usage: per generated image, video or 3D model, and powerful GPUs can be rented for custom workloads. The service positions itself as a low-cost alternative to other serverless AI providers.', 'Запуск моделей одним рядком коду
Генерація зображень, відео, 3D і мовлення
Реставрація й підписування зображень
Дотренування моделей
Оплата за кожен результат
Оренда графічних процесорів', 'Run models with one line of code
Image, video, 3D and speech generation
Image restoration and captioning
Model fine-tuning
Pay per output
GPU rental', 'Розробники й стартапи, які вбудовують генеративні моделі у свої продукти.', 'Developers and startups building generative models into their products.', 'web', 'course', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
