-- ScanRelief — Фінанси
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'scanrelief.com' OR LOWER(`name`) = LOWER('ScanRelief'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ScanRelief', NULL, 'https://scanrelief.com', NULL, NULL, 'Програма для Windows і Mac, яка за допомогою OpenAI розпізнає чеки й рахунки в папці на вашому диску, перейменовує файли за датою, сумою, типом покупки й продавцем і складає з них таблицю Excel.', 'A Windows and Mac app that uses OpenAI to read receipts and invoices in a folder on your drive, renames the files by date, amount, purchase type and vendor, and compiles them into an Excel sheet.', 'ScanRelief допомагає впорядкувати чеки й рахунки для бухгалтерії без ручного сортування. Програма сканує папку з файлами чеків на вашому комп''ютері, аналізує їх за допомогою OpenAI й перейменовує так, щоб назва починалася з дати, а далі йшли сума, тип покупки й компанія. Завдяки цьому файли автоматично сортуються за часом у провіднику Windows чи Finder на Mac, і їх легко зіставляти з банківськими операціями. Окрім перейменування, програма створює детальний звіт Excel з усіма чеками. Файли не потрібно завантажувати на сторонній вебсервіс: програма працює локально, а оплачується лише фактичне використання OpenAI за вашим ключем. Ліцензія безстрокова з разовою оплатою; є безкоштовна версія для завантаження.', 'ScanRelief helps you organize receipts and invoices for bookkeeping without manual sorting. The app scans a folder of receipt files on your computer, analyzes them with OpenAI and renames them so that the name starts with the date, followed by the amount, purchase type and company. As a result the files sort chronologically in Windows Explorer or the Mac Finder and are easy to match with bank transactions. Besides renaming, the app creates a detailed Excel report of all receipts. Files do not need to be uploaded to a third-party web service: the app runs locally, and you only pay for actual OpenAI usage with your own key. The license is perpetual with a one-time payment; a free version is available to download.', 'Розпізнавання чеків і рахунків через OpenAI
Перейменування файлів за датою, сумою й продавцем
Звіт Excel з усіма чеками
Локальна робота без завантаження у хмару
Windows і Mac
Безстрокова ліцензія', 'Receipt and invoice recognition via OpenAI
Renaming files by date, amount and vendor
Excel report of all receipts
Local processing with no cloud upload
Windows and Mac
Perpetual license', 'Фрилансери, підприємці й невеликі компанії, які ведуть облік витрат.', 'Freelancers, entrepreneurs and small companies tracking expenses.', 'desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
