-- AIMusicGen — Музика
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aimusicgen.ai' OR LOWER(`name`) = LOWER('AIMusicGen'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'AIMusicGen', NULL, 'https://aimusicgen.ai', NULL, NULL, 'AI-генератор музики: створює оригінальні пісні з опису чи ваших слів у будь-якому стилі, інструментальні треки й музичні відео, з редагуванням, реміксами, стемами й видаленням вокалу.', 'An AI music generator: it creates original songs from a description or your own lyrics in any style, instrumental tracks and music videos, with editing, remixes, stems and vocal removal.', 'AIMusicGen перетворює ідею на пісню. Опишіть, яку музику хочете — жанр, настрій, інструменти, вокал, — або вставте власні слова, оберіть одну з кількох моделей генерації й отримайте готовий трек; можна також створити інструментальну композицію. З пісні можна зробити музичне відео з кінематографічними сценами чи виступом. На платних тарифах доступні редагування пісні, ремікси, розділення на стеми, видалення й зміна вокалу, завантаження без втрати якості, зображення й відео у 4K, приватна генерація та комерційна ліцензія. Безкоштовний тариф дає кілька кредитів, що оновлюються щодня; невикористані платні кредити переносяться.', 'AIMusicGen turns an idea into a song. Describe the music you want, including genre, mood, instruments and vocals, or paste your own lyrics, choose one of several generation models and get a finished track; you can also create an instrumental piece. A song can be turned into a music video with cinematic scenes or a performance. Paid plans add song editing, remixes, stem separation, vocal removal and changing, lossless downloads, 4K images and video, private generation and a commercial license. The free plan gives a few credits that refresh daily; unused paid credits carry over.', 'Пісні з опису чи ваших слів
Інструментальні треки
Кілька моделей генерації
Музичні відео
