-- GPT-trainer — Чат-боти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gpt-trainer.com' OR LOWER(`name`) = LOWER('GPT-trainer'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'GPT-trainer', NULL, 'https://gpt-trainer.com', NULL, NULL, 'No-code платформа для створення голосових і текстових AI-агентів для бізнесу: підтримка клієнтів, кваліфікація лідів, навчання персоналу й внутрішня допомога — у телефонних дзвінках, пошті, SMS, вебчаті й соцмережах.', 'A no-code platform for building voice and text AI agents for business: customer support, lead qualification, staff training and internal help across phone calls, email, SMS, web chat and social media.', 'GPT-trainer дозволяє компаніям створювати AI-агентів, що працюють з клієнтами й співробітниками через телефон, електронну пошту, SMS, чат на сайті та соцмережі. Платформа поєднує систему з кількох агентів, конструктор без коду й API, тож налаштування займає небагато часу. Серед типових сценаріїв — цілодобова підтримка клієнтів у всіх каналах, кваліфікація й розподіл лідів, створення маркетингового контенту, навчання й адаптація персоналу, відповіді на внутрішні HR- та IT-запитання, допомога викладачам і студентам, аналіз документів і впорядкування неструктурованих даних. Агентів можна налаштувати під стиль бренду й внутрішні правила. Почати можна безкоштовно з двотижневим пробним періодом розширених можливостей; для великих компаній є виділена чи локальна інфраструктура, повний white label і підключення власних моделей.', 'GPT-trainer lets companies build AI agents that work with customers and employees by phone, email, SMS, website chat and social media. The platform combines a multi-agent system, a no-code builder and an API, so setup takes little time. Typical scenarios include 24/7 omnichannel customer support, lead qualification and routing, marketing content creation, staff training and onboarding, answering internal HR and IT questions, helping teachers and students, document analysis and structuring unstructured data. Agents can be tuned to your brand voice and internal policies. You can start for free with a two-week trial of advanced features; large companies get dedicated or on-premise infrastructure, full white label and custom model integration.', 'Голосові й текстові AI-агенти
Телефон, пошта, SMS, вебчат і соцмережі
Конструктор без коду й API
Цілодобова підтримка клієнтів
Кваліфікація лідів
Аналіз документів
White label і власні моделі (Enterprise)', 'Voice and text AI agents
Phone, email, SMS, web chat and social media
No-code builder and API
24/7 customer support
Lead qualification
Document analysis
